import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// Generated by `just regenerate-licenses`.
const _assetPath = 'assets/licenses/rust_licenses.json';

/// Registers the licenses of the Rust dependencies in the [LicenseRegistry],
/// next to the Dart ones Flutter registers itself.
void registerRustLicenses() {
  LicenseRegistry.addLicense(rustLicenses);
}

/// One entry per license text, listing the crates it applies to.
Stream<LicenseEntry> rustLicenses() async* {
  final json = await rootBundle.loadString(_assetPath, cache: false);
  final entries = await compute(_parse, json);
  for (final (crates, text) in entries) {
    yield LicenseEntryWithLineBreaks(crates, text);
  }
}

List<(List<String>, String)> _parse(String json) {
  final licenses =
      (jsonDecode(json) as Map<String, dynamic>)['licenses'] as List<dynamic>;
  return [
    for (final license in licenses.cast<Map<String, dynamic>>())
      (
        {
          for (final crate
              in (license['used_by'] as List<dynamic>)
                  .cast<Map<String, dynamic>>())
            crate['name'] as String,
        }.toList(),
        license['text'] as String,
      ),
  ];
}
